/**
 * Brand emblems from @cardog-icons/core (synced to public/brands/).
 * Map is generated by scripts/sync-brand-emblems.mjs on npm install.
 * UI uses sprite symbols; charts/PNG export still use per-brand SVG files.
 */
import emblemMapFile from './brandEmblemMap.generated.json';
import { isDocumentDarkNow } from '../composables/useDocumentDarkMode';

const EMBLEM_BY_BRAND = emblemMapFile.brands || {};

/** @type {Map<string, string>} brand → slug (hot path cache) */
const slugCache = new Map();

function brandEmblemUrl(fileBase) {
  const base = import.meta.env.BASE_URL || '/';
  const root = base.endsWith('/') ? base : `${base}/`;
  return `${root}brands/${fileBase}.svg`;
}

export function getBrandEmblemSlug(brand) {
  if (!brand) return null;
  if (slugCache.has(brand)) return slugCache.get(brand);
  const slug = EMBLEM_BY_BRAND[brand] || null;
  slugCache.set(brand, slug);
  return slug;
}

export function hasBrandEmblem(brand) {
  return Boolean(getBrandEmblemSlug(brand));
}

/** Sprite symbol id for <use href="#…"> (injected sprite). */
export function getBrandEmblemSymbolId(brand, opts = {}) {
  const slug = getBrandEmblemSlug(brand);
  if (!slug) return null;
  const dark = opts.dark != null ? opts.dark : isDocumentDarkNow();
  return dark ? `be-${slug}-dark` : `be-${slug}`;
}

/**
 * @param {string} brand - AALA brand label
 * @param {{ dark?: boolean }} [opts] - defaults to current document theme
 */
export function getBrandEmblemUrl(brand, opts = {}) {
  const slug = getBrandEmblemSlug(brand);
  if (!slug) return null;
  const dark = opts.dark != null ? opts.dark : isDocumentDarkNow();
  return brandEmblemUrl(dark ? `${slug}-dark` : slug);
}

/** Resolve href for chart/PNG emblem markers (theme-aware file URL). */
export function resolveEmblemUrl(style, brandHint) {
  if (!style) return null;
  const brand = style.emblemBrand || brandHint;
  if (brand && hasBrandEmblem(brand)) return getBrandEmblemUrl(brand);
  return style.emblemUrl || null;
}

export function brandEmblemCoverage() {
  return {
    mapped: emblemMapFile.mappedCount ?? Object.keys(EMBLEM_BY_BRAND).length,
    aalaTotal: emblemMapFile.aalaBrandCount ?? null,
  };
}

export function brandEmblemSpriteUrl() {
  const base = import.meta.env.BASE_URL || '/';
  const root = base.endsWith('/') ? base : `${base}/`;
  return `${root}brands/sprite.svg`;
}

const SPRITE_HOST_ID = 'brand-emblem-sprite-host';
let spritePromise = null;

/** Fetch and inject the emblem sprite once into document.body. */
export function ensureBrandEmblemSprite() {
  if (typeof document === 'undefined') return Promise.resolve(false);
  if (document.getElementById(SPRITE_HOST_ID)) return Promise.resolve(true);
  if (spritePromise) return spritePromise;

  spritePromise = (async () => {
    try {
      if (document.getElementById(SPRITE_HOST_ID)) return true;
      const res = await fetch(brandEmblemSpriteUrl());
      if (!res.ok) return false;
      const text = await res.text();
      const host = document.createElement('div');
      host.id = SPRITE_HOST_ID;
      host.setAttribute('hidden', '');
      host.setAttribute('aria-hidden', 'true');
      host.style.cssText = 'position:absolute;width:0;height:0;overflow:hidden';
      host.innerHTML = text;
      document.body.prepend(host);
      return true;
    } catch {
      return false;
    } finally {
      // Allow retry if injection failed
      if (!document.getElementById(SPRITE_HOST_ID)) spritePromise = null;
    }
  })();

  return spritePromise;
}
